#include <iostream>
#include <opencv2/opencv.hpp>

using namespace cv;

void detectFaces(const Mat& image) {
    // Load the pre-trained face detector
    CascadeClassifier faceDetector = CascadeClassifier("haarcascade_frontalface_default.xml");

    // Check if the face detector is loaded correctly
    if (!faceDetector.load("haarcascade_frontalface_default.xml")) {
        std::cout << "Error loading face detector." << std::endl;
        return;
    }

    // Detect faces in the image
    std::vector<Rect> faces;
    faceDetector.detectMultiScale(image, faces);

    // Draw rectangles around the detected faces
    for (const Rect& face : faces) {
        rectangle(image, face, Scalar(0, 255, 0), 2);
    }

    // Display the image with detected faces
    imshow("Faces", image);
    waitKey(0);
    destroyAllWindows();
}

