  {0x00, 0x00}, // Point 0
  {0x0A, 0x01}, // Point 1
  {0x1B, 0x02}, // Point 2
  {0x2C, 0x03}, // Point 3
  {0x3D, 0x04}, // Point 4
  {0x4E, 0x05}, // Point 5
  {0x5F, 0x06}, // Point 6
  {0x68, 0x07}, // Point 7
  {0x79, 0x08}, // Point 8
  {0x8A, 0x09}, // Point 9
  {0x99, 0x10}  // Point 10
};

// Function to perform 11-point linear interpolation
uint16_t interpolate(uint16_t adc_value) {
  uint16_t interpolated_value = 0;
  uint16_t step = (adc_value * POINTS_PER_STEP) / 1024; // Scale the ADC value to the 0-10 range
  uint16_t frac = (adc_value * (NUM_POINTS - 1)) / 1024; // Calculate the fractional part of the step

  // Find the two points that surround the interpolated value
  uint16_t point_1 = interpolation_table[step].adc_value;
  uint16_t point_2 = interpolation_table[step + 1].adc_value;
  uint16_t output_1 = interpolation_table[step].output_value;
  uint16_t output_2 = interpolation_table[step + 1].output_value;

  // Perform linear interpolation
  interpolated_value = (uint16_t)(((output_2 - output_1) * frac) + output_1);

  return interpolated_value;
}
