// Define the number of calibration points
#define NUM-points 11

// Define the calibration points (Vref and ADC counts)
struct CalibrationPoint {
    float Vref;      // Reference voltage (V)
    uint16_t ADC;    // ADC counts
};

extern struct CalibrationPoint calibration_points[NUM_points];

// Define the linear interpolation function
uint16_t linear_interpolation(float V, struct CalibrationPoint *p1, struct CalibrationPoint *p2) {
    float slope = (p2->ADC - p1->ADC) / (p2->Vref - p1->Vref);
    float intercept = p1->ADC - slope * p1->Vref;
    return (uint16_t)((slope * V + intercept + 0.5));
}

// Define the main calibration function
uint16_t adc_calibrate(float V) {
    // Find the two closest points to the given voltage
    int idx1 = 0;
    int idx2 = 0;
    float min_diff = 1000.0f;
    for (int i = 0; i < NUM_points; i++) {
        float diff = abs(calibration_points[i].Vref - V);
        if (diff < min_diff) {
            min_diff = diff;
            idx1 = i;
        }
    }
    for (int i = 0; i < NUM_points; i++) {
        float diff = abs(calibration_points[i].Vref - V);
        if (diff < min_diff && i != idx1) {
            min_diff = diff;
            idx2 = i;
        }
    }

    // Perform linear interpolation
    return linear_interpolation(V, &calibration_points[idx1], &calibration_points[idx2]);
